function CreatableSelect({ label, value, onChange, options, allowCreate = true }) {
  const [adding, setAdding] = useState(false);
  const [newVal, setNewVal] = useState("");
  const confirmAdd = () => {
    const v = newVal.trim();
    if (v) onChange(v);
    setAdding(false);
    setNewVal("");
  };
  if (adding) {
    return (
      /* @__PURE__ */ <div style={{ marginBottom: 13 }}>
        <label style={{ fontSize: 12, fontWeight: 600, color: "#555", display: "block", marginBottom: 4 }}>
          {label}
        </label>
        <div style={{ display: "flex", gap: 6 }}>
          <input
            autoFocus={true}
            value={newVal}
            onChange={(e) => setNewVal(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") confirmAdd();
              if (e.key === "Escape") setAdding(false);
            }}
            placeholder="Nouvel élément..."
            style={{
              flex: 1,
              padding: "8px 11px",
              border: `1px solid ${C.navy}`,
              borderRadius: 8,
              fontSize: 13,
              fontFamily: "inherit",
              boxSizing: "border-box",
            }}
          />
          <button
            onClick={confirmAdd}
            title="Ajouter"
            style={{
              border: "none",
              background: C.green,
              color: "white",
              borderRadius: 8,
              padding: "0 13px",
              cursor: "pointer",
              fontWeight: 700,
              fontFamily: "inherit",
            }}
          >
            ✓
          </button>
          <button
            onClick={() => {
              setAdding(false);
              setNewVal("");
            }}
            title="Annuler"
            style={{
              border: "none",
              background: C.light,
              color: "#555",
              borderRadius: 8,
              padding: "0 13px",
              cursor: "pointer",
              fontFamily: "inherit",
            }}
          >
            ✕
          </button>
        </div>
      </div>
    );
  }
  const allOptions = value && !options.includes(value) ? [value, ...options] : options;
  return (
    /* @__PURE__ */ <Sel
      label={label}
      value={value}
      onChange={(e) => {
        if (e.target.value === "__add__") setAdding(true);
        else onChange(e.target.value);
      }}
    >
      <option value="">-- Sélectionner --</option>
      {allOptions.map((o) => (
        /* @__PURE__ */ <option key={o} value={o}>
          {o}
        </option>
      ))}
      {allowCreate && <option value="__add__">➕ Ajouter un nouvel élément...</option>}
    </Sel>
  );
}
