    const heuresMois = {};
    const heuresSemaine = {};
    const semaines = { "Semestre 1": new Map(), "Semestre 2": new Map() };
    p.occurrences.forEach((o) => {
      const m = o.date.slice(0, 7);
      const lundi = _lundiPrev(o.date);
      heuresMois[m] = (heuresMois[m] || 0) + o.duree;
      heuresSemaine[`${m}|${lundi}`] = (heuresSemaine[`${m}|${lundi}`] || 0) + o.duree;
      if (semaines[o.semestre]) semaines[o.semestre].set(lundi, (semaines[o.semestre].get(lundi) || 0) + o.duree);
    });
