    const jour = Math.min(28, Math.max(1, parseInt(data.configuration?.jourDebutPeriodePointage, 10) || 26));
    if (jour === 1) return { debut: fmt(new Date(y, m - 1, 1)), fin: fmt(new Date(y, m, 0)) };
