// ── Impression : hub centralisant tous les documents imprimables de
// l'application (attestations, convention de stage, relevés de notes,
// relevés d'absences, liste d'un groupe, fiche de présence hebdomadaire),
// filtrables par année universitaire / groupe / semestre selon le
// document concerné — réservé à l'administrateur et à la direction.
// Affiche le guide d'utilisation correspondant au rôle directement dans le
// navigateur (dans un cadre intégré à la page), sans jamais le télécharger.
// Pour un étudiant, la brochure est ENTIÈREMENT PERSONNALISÉE : générée à
// la volée dans son propre navigateur (via genererBrochureGuideComplete),
// avec ses vraies coordonnées de connexion — jamais transmise ni stockée
// ailleurs que dans la mémoire de son propre appareil, via une URL "blob"
// locale. Pour les autres rôles (professeur, direction, administrateur),
// le guide générique illustré reste affiché depuis un fichier PDF externe,
// à déposer par l'administrateur sous ces noms exacts, dans le même
// dossier GitHub que ECOGEST.html.
const GUIDES = {
  // Guide illustré de l'étudiant : page web légère (images chargées au fil de
  // la lecture) + version PDF, dans le dossier guide_etudiant/ à côté d'ECOGEST.html.
  etudiant: {
    fichier: "./guide_etudiant/guide.html",
    pdf: "./guide_etudiant/Guide_Etudiant_ECOGEST.pdf",
    label: "Guide Étudiant",
  },
  professeur: { fichier: "./Brochure_ECOGEST_Professeur.pdf", label: "Guide Professeur" },
};
function GuidePage({ role, data, user }) {
  const monEtudiant = (data.etudiants || []).find((e) => user?.etudiantId && e.id === user.etudiantId);
  const monProfesseur = (data.professeurs || []).find(
    (p) => p.email && user?.email && p.email.toLowerCase() === user.email.toLowerCase()
  );
  const guidesDisponibles =
    role === "etudiant" ? ["etudiant"] : role === "professeur" ? ["professeur"] : ["etudiant", "professeur"];
  const [guideActif, setGuideActif] = useState(guidesDisponibles[0]);
  const [urlBrochurePerso, setUrlBrochurePerso] = useState(null);
  const [erreurGeneration, setErreurGeneration] = useState(false);
  const estEtudiantPersonnalise = role === "etudiant";
  const estProfPersonnalise = role === "professeur";
  // Étudiant : le guide illustré s'affiche d'abord ; la brochure personnalisée
  // (avec ses identifiants) n'est générée que s'il la demande — l'ouverture
  // de la page reste instantanée.
  const [vue, setVue] = useState(estEtudiantPersonnalise ? "guide" : "brochure");
  const personnePersonnalisee = estEtudiantPersonnalise ? monEtudiant : estProfPersonnalise ? monProfesseur : null;
  const brochureDemandee = (estEtudiantPersonnalise || estProfPersonnalise) && vue === "brochure";
  // Personnalisation ENTIÈREMENT LOCALE au navigateur : la brochure est
  // générée à la volée, sans jamais être transmise ni stockée ailleurs
  // qu'en mémoire, via une URL "blob".
  useEffect(() => {
    if (!brochureDemandee || !personnePersonnalisee) {
      setUrlBrochurePerso(null);
      return;
    }
    let annule = false;
    let urlCreee = null;
    setErreurGeneration(false);
    (async () => {
      try {
        const urlApplication = `${location.origin}${location.pathname}`;
        const doc = new MiniPDF(210 * MM, 297 * MM);
        if (estEtudiantPersonnalise) {
          await genererBrochureGuideComplete(personnePersonnalisee, urlApplication, doc);
        } else {
          await genererBrochureGuideCompleteProf(personnePersonnalisee, urlApplication, doc);
        }
        if (annule) return;
        const blob = new Blob([doc.build()], { type: "application/pdf" });
        urlCreee = URL.createObjectURL(blob);
        setUrlBrochurePerso(urlCreee);
      } catch (e) {
        console.error("Erreur génération brochure personnalisée :", e);
        if (!annule) setErreurGeneration(true);
      }
    })();
    return () => {
      annule = true;
      if (urlCreee) URL.revokeObjectURL(urlCreee);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    brochureDemandee,
    role,
    personnePersonnalisee?.id,
    personnePersonnalisee?.email,
    personnePersonnalisee?.motDePasse,
    personnePersonnalisee?.numInscription,
  ]);

  const estPersonnalise = brochureDemandee;
  const guide = GUIDES[guideActif];
  const srcActif = estPersonnalise ? urlBrochurePerso : guide.fichier;
  const styleBouton = (actif) => ({
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    padding: "8px 14px",
    borderRadius: 9,
    fontSize: 13,
    fontWeight: 700,
    cursor: "pointer",
    textDecoration: "none",
    border: actif ? `1.5px solid ${C.navy}` : "1.5px solid #d5dce8",
    background: actif ? C.navy : "#fff",
    color: actif ? "#fff" : C.navy,
  });

  return (
    /* @__PURE__ */ <div>
      <h2 style={{ color: C.navy, marginBottom: 4 }}>📖 Guide d'utilisation</h2>
      <p style={{ color: C.muted, fontSize: 13, marginTop: 0, marginBottom: 14 }}>
        {estPersonnalise
          ? "Voici votre brochure personnalisée, avec vos propres paramètres de connexion — générée directement dans votre navigateur, elle n'est ni envoyée ni stockée ailleurs."
          : guideActif === "etudiant"
            ? "Toutes les opérations de l'espace étudiant, pas à pas, avec un aperçu de chaque écran. Les images se chargent au fil de la lecture."
            : "Consultez ci-dessous le guide illustré d'ECOGEST, directement dans votre navigateur — aucun téléchargement n'est nécessaire."}
      </p>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 14 }}>
        {estEtudiantPersonnalise ? (
          /* @__PURE__ */ <>
            <button type="button" style={styleBouton(vue === "guide")} onClick={() => setVue("guide")}>
              📘 Guide illustré
            </button>
            <button type="button" style={styleBouton(vue === "brochure")} onClick={() => setVue("brochure")}>
              🔐 Ma brochure personnalisée
            </button>
          </>
        ) : (
          guidesDisponibles.length > 1 &&
          guidesDisponibles.map((g) => (
            /* @__PURE__ */ <button key={g} type="button" style={styleBouton(guideActif === g)} onClick={() => setGuideActif(g)}>
              {GUIDES[g].label}
            </button>
          ))
        )}
        {!estPersonnalise && guide.pdf && (
          /* @__PURE__ */ <a href={guide.pdf} download style={{ ...styleBouton(false), marginLeft: "auto", borderColor: "#E8833A", color: "#B85A12" }}>
            ⬇ Télécharger le PDF
          </a>
        )}
      </div>
      {estPersonnalise && !personnePersonnalisee ? (
        /* @__PURE__ */ <Card style={{ padding: 20, textAlign: "center", color: C.muted }}>
          {estEtudiantPersonnalise
            ? "Votre fiche étudiant est introuvable — impossible de générer votre brochure personnalisée. Contactez l'administration."
            : "Votre fiche professeur est introuvable — impossible de générer votre brochure personnalisée. Contactez l'administration."}
        </Card>
      ) : estPersonnalise && erreurGeneration ? (
        /* @__PURE__ */ <Card style={{ padding: 20, textAlign: "center", color: C.red }}>
          Une erreur est survenue pendant la génération de votre brochure. Rechargez la page pour réessayer.
        </Card>
      ) : estPersonnalise && !urlBrochurePerso ? (
        /* @__PURE__ */ <Card style={{ padding: 20, textAlign: "center", color: C.muted }}>
          Génération de votre brochure en cours...
        </Card>
      ) : (
        /* @__PURE__ */ <Card style={{ padding: 0, overflow: "hidden" }}>
          <iframe
            key={srcActif}
            src={srcActif}
            title={estPersonnalise ? "Ma brochure ECOGEST" : guide.label}
            style={{ width: "100%", height: "80vh", border: "none", display: "block", background: "#eef2f8" }}
          />
        </Card>
      )}
      {srcActif && (
        /* @__PURE__ */ <p style={{ fontSize: 11.5, color: C.muted, marginTop: 10 }}>
          Le guide ne s'affiche pas ?{" "}
          <a href={srcActif} target="_blank" rel="noreferrer">
            Ouvrez-le dans un nouvel onglet
          </a>
          .
        </p>
      )}
    </div>
  );
}
