  // Version triée par Groupe puis Nom/Prénom pour l'affichage du tableau
  // de prévisualisation ci-dessous.
  const etudiantsAvecAbsenceFiltreeTriee = [...etudiantsAvecAbsenceFiltree].sort(
    (a, b) =>
      (a.filiere || "").localeCompare(b.filiere || "", "fr", { sensitivity: "base" }) ||
      (a.nom || "").localeCompare(b.nom || "", "fr", { sensitivity: "base" }) ||
      (a.prenom || "").localeCompare(b.prenom || "", "fr", { sensitivity: "base" })
  );
  // --- Section "Relevés des paiements" : même principe que les relevés de
  // notes/absences, rapproché avec le résumé de paiement de chaque
  // étudiant (data.paiements.etudiants_paiement) pour l'année choisie.
  const etudiantsBasePaiements = (data.etudiants || [])
    .filter((e) => e.statut !== "Inactif")
    .filter((e) => {
      const filiereActuelle = filiereEtudiantPourAnnee(e, releveFilterAnnee);
      if (!filiereActuelle) return false;
      if (releveFilterGroupe.length > 0 && !releveFilterGroupe.includes(filiereActuelle)) return false;
      return (
        e.promotion === releveFilterAnnee ||
        (e.parcours || []).some((p) => p.anneeUniversitaire === releveFilterAnnee)
      );
    })
    .filter(
      (e) =>
        !releveSearch ||
        `${e.prenom || ""} ${e.nom || ""} ${e.numInscription || ""}`
          .toLowerCase()
          .includes(releveSearch.toLowerCase())
    );
  // Une ligne par étudiant filtré, avec sa fiche de paiement correspondant
  // à l'année choisie si elle existe (sinon une fiche vide à zéro, pour ne
  // jamais exclure un étudiant simplement parce qu'aucun paiement n'a
  // encore été saisi pour lui).
  const lignesPaiementsImpression = etudiantsBasePaiements
    .map((e) => {
      const ep = (data.paiements?.etudiants_paiement || []).find(
        (p) => p.etudiantId === e.id && (!releveFilterAnnee || p.promotion === releveFilterAnnee)
      );
      return {
        id: e.id,
        etudiantId: e.id,
        etudiant: `${e.nom || ""} ${e.prenom || ""}`.trim(),
        numInscription: e.numInscription,
        filiere: filiereEtudiantPourAnnee(e, releveFilterAnnee) || e.filiere,
        totalAPayer: ep?.totalAPayer || 0,
        totalPaye: ep?.totalPaye || 0,
        solde: (ep?.totalAPayer || 0) - (ep?.totalPaye || 0),
        formationGratuite: !!e.formationGratuite,
        _ep: ep || null,
        _etudiant: e,
      };
    })
    // Triées par Groupe puis Nom/Prénom pour l'affichage du tableau de
    // prévisualisation ci-dessous.
    .sort(
      (a, b) =>
        (a.filiere || "").localeCompare(b.filiere || "", "fr", { sensitivity: "base" }) ||
        (a._etudiant.nom || "").localeCompare(b._etudiant.nom || "", "fr", { sensitivity: "base" }) ||
        (a._etudiant.prenom || "").localeCompare(b._etudiant.prenom || "", "fr", { sensitivity: "base" })
    );
  // --- « Documents de l'intervenant » : uniquement les professeurs
  // vacataires principaux (les permanents et les professeurs alternatifs en
  // sont exclus). Un intervenant figure dans la liste s'il est rattaché à
  // l'année choisie (fiche professeur), ou s'il y a des séances ou des
  // modules ; les autres filtres affinent ensuite la liste.
  const intervenantsFiltres = (data.professeurs || [])
    .filter((p) => p.principal !== false && p.type !== "Permanent")
    .map((p) => {
      const seances = seancesIntervenant(data, p, intAnnee, intSemestre);
      const modules = coursIntervenant(data, p, intAnnee, intSemestre);
      return { ...p, _seances: seances, _modules: modules };
    })
    .filter((p) => {
      const annees = p.anneesUniversitaires || [];
      const rattache = !intAnnee || annees.length === 0 || annees.includes(intAnnee);
      if (!rattache && p._seances.length === 0 && p._modules.length === 0) return false;
      if (intStatut && (p.statut || "Actif") !== intStatut) return false;
      if (intActivite === "avec" && p._seances.length === 0) return false;
      if (intActivite === "sans" && p._seances.length > 0) return false;
      if (intMode && !p._seances.some((s) => modeEnseignementSeance(s) === intMode)) return false;
      if (
        intGroupes.length > 0 &&
        !p._seances.some((s) => intGroupes.includes(s.filiere)) &&
        !p._modules.some((c) => (c.filieresListe || [c.filiere]).some((f) => intGroupes.includes(f)))
      )
        return false;
      if (intModule && !p._seances.some((s) => s.module === intModule) && !p._modules.some((c) => c.intitule === intModule))
        return false;
      if (intSearch) {
        const q = intSearch.toLowerCase();
        if (!`${p.nom || ""} ${p.prenom || ""} | ${p.prenom || ""} ${p.nom || ""} | ${p.cin || ""} | ${p.email || ""}`.toLowerCase().includes(q))
          return false;
      }
      return true;
    })
    .sort(
      (a, b) =>
        (a.nom || "").localeCompare(b.nom || "", "fr", { sensitivity: "base" }) ||
        (a.prenom || "").localeCompare(b.prenom || "", "fr", { sensitivity: "base" })
    );
  const intervenantsCoches = intervenantsFiltres.filter((p) => selectionIntervenants.includes(p.id));
  const intervenantsCibles = intervenantsCoches.length > 0 ? intervenantsCoches : intervenantsFiltres;
  const tousIntervenantsCoches = intervenantsFiltres.length > 0 && intervenantsCoches.length === intervenantsFiltres.length;
  const basculerIntervenant = (id) =>
    setSelectionIntervenants((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  const basculerTousIntervenants = () =>
    setSelectionIntervenants((s) =>
      tousIntervenantsCoches
        ? s.filter((id) => !intervenantsFiltres.some((p) => p.id === id))
        : [...new Set([...s, ...intervenantsFiltres.map((p) => p.id)])]
    );
  const modulesOptionsIntervenants = [
    ...new Set([
      ...(data.emploiDuTemps || []).filter((s) => !intAnnee || s.anneeUniversitaire === intAnnee).map((s) => s.module),
      ...(data.cours || []).filter((c) => !intAnnee || (c.anneesUniversitaires || []).includes(intAnnee)).map((c) => c.intitule),
    ].filter(Boolean)),
  ].sort((a, b) => a.localeCompare(b, "fr", { sensitivity: "base" }));
  const nomIntervenant = (p) => [civiliteProfesseur(p), `${p.prenom || ""} ${p.nom || ""}`.trim()].filter(Boolean).join(" ");
  const semestresIntervenant = intSemestre ? [intSemestre] : ["Semestre 1", "Semestre 2"];
  const codeGroupe = (intitule) => filiereCode(intitule, data.filieres) || intitule;
  // Planification des cours de l'intervenant : une page (paysage) par
  // semestre où il a des séances. Les séances communes à plusieurs groupes
  // (même jour, créneau, module et période) forment une seule carte qui
  // liste tous les groupes concernés.
  const ajouterPlanificationIntervenant = (p, doc, premierePage) => {
    let pages = 0;
    semestresIntervenant.forEach((sem) => {
      const seances = seancesIntervenant(data, p, intAnnee, sem);
      if (seances.length === 0) return;
      const fusion = new Map();
      seances.forEach((s) => {
        const cle = [s.jour, seanceClef(s.seance), s.module, s.dateDebut || "", s.dateFin || ""].join("|");
        if (!fusion.has(cle)) fusion.set(cle, { ...s, _groupes: [] });
        const c = fusion.get(cle);
        if (!c._groupes.includes(s.filiere)) c._groupes.push(s.filiere);
      });
      const creneaux = [...fusion.values()];
      const vus = new Set();
      const lignes = trierParHoraire(
        creneaux
          .map((c) => c.seance)
          .filter((s) => {
            const k = seanceClef(s);
            if (vus.has(k)) return false;
            vus.add(k);
            return true;
          })
      );
      if (!premierePage || pages > 0) doc.newPage();
      genererEmploiDuTempsGroupe(null, creneaux, lignes, JOURS_SEMAINE, sem, intAnnee, data.cours || [], {
        titre: `PLANIFICATION DES COURS — ${nomIntervenant(p)}`,
        ligneCarte: (c) => c._groupes.map(codeGroupe).join(" · "),
        docExterne: doc,
      });
      pages += 1;
    });
    return pages;
  };
  // Calendrier des examens de l'intervenant : CC et EFM de ses modules, par
  // groupe, triés par date (un même examen commun à plusieurs groupes ne
  // forme qu'une ligne).
  const lignesCalendrierIntervenant = (p) => {
    const paires = new Map();
    semestresIntervenant.forEach((sem) =>
      modulesParGroupeIntervenant(data, p, intAnnee, sem).forEach((g) =>
        g.modules.forEach((m) => paires.set(`${g.filiere}|||${m}`, { filiere: g.filiere, module: m }))
      )
    );
    const parExamen = new Map();
    paires.forEach(({ filiere, module }) => {
      [
        ["dateCC", "Contrôle continu"],
        ["dateExamen", "Examen"],
      ].forEach(([champ, type]) => {
        const date = dateEvaluationModuleGroupe(data.cours, module, filiere, intAnnee, champ);
        if (!date) return;
        const cle = `${date}|${type}|${module}`;
        if (!parExamen.has(cle)) parExamen.set(cle, { date, type, module, groupes: [] });
        parExamen.get(cle).groupes.push(codeGroupe(filiere));
      });
    });
    return [...parExamen.values()]
      .map((l) => ({ ...l, professeur: [...new Set(l.groupes)].join(", ") }))
      .sort(
        (a, b) =>
          a.date.localeCompare(b.date) ||
          a.type.localeCompare(b.type, "fr") ||
          a.module.localeCompare(b.module, "fr", { sensitivity: "base" })
      );
  };
  // Calendrier ESRMI de l'intervenant : périodes calculées sur les groupes
  // où il enseigne cette année.
  const lignesCalendrierESRMIIntervenant = (p) => {
    const groupes = new Set(seancesIntervenant(data, p, intAnnee, "").map((s) => s.filiere).filter(Boolean));
    coursIntervenant(data, p, intAnnee, "").forEach((c) =>
      ((c.filieresListe || []).length ? c.filieresListe : [c.filiere]).forEach((f) => f && groupes.add(f))
    );
    return lignesCalendrierESRMI(data, groupes, intAnnee, semestresIntervenant);
  };
  const optsCalendrierIntervenant = (p, doc) => ({
    titre: nomIntervenant(p),
    libelleDerniereColonne: "Groupe(s)",
    docExterne: doc,
    nomFichier: `Calendrier_Examens_${p.prenom || ""}_${p.nom || ""}_${intAnnee}.pdf`.replace(/\s+/g, "_"),
  });
  const libelleSemestreIntervenant = intSemestre || "Semestres 1 et 2";
  // Génère un document pour UN intervenant (icône du tableau) ou pour tous
  // les intervenants cochés / filtrés (boutons du haut), dans un seul PDF.
  const imprimerDocumentsIntervenants = async (typeDoc, liste) => {
    if (liste.length === 0) {
      toast("⚠️ Aucun intervenant ne correspond aux filtres actuels");
      return;
    }
    const seul = liste.length === 1;
    const paysage = typeDoc === "planification";
    const doc = paysage ? new MiniPDF(297 * MM, 210 * MM) : new MiniPDF(210 * MM, 297 * MM);
    let nbDocs = 0;
    const ignores = [];
    for (const p of liste) {
      if (typeDoc === "planification") {
        const n = ajouterPlanificationIntervenant(p, doc, nbDocs === 0);
        if (n > 0) nbDocs += 1;
        else ignores.push(nomIntervenant(p));
      } else if (typeDoc === "calendrier") {
        const lignes = lignesCalendrierIntervenant(p);
        if (lignes.length === 0) {
          ignores.push(nomIntervenant(p));
          continue;
        }
        if (nbDocs > 0) doc.newPage();
        genererCalendrierExamensGroupe(null, lignes, libelleSemestreIntervenant, intAnnee, optsCalendrierIntervenant(p, doc));
        nbDocs += 1;
      } else if (typeDoc === "esrmi") {
        if (nbDocs > 0) doc.newPage();
        genererCalendrierESRMI(lignesCalendrierESRMIIntervenant(p), intAnnee, nomIntervenant(p), doc);
        nbDocs += 1;
      } else if (typeDoc === "engagement") {
        if (nbDocs > 0) doc.newPage();
        genererEngagementEnseignant(
          p,
          modulesParGroupeIntervenant(data, p, intAnnee, intSemestre),
          intAnnee,
          data.filieres || [],
          doc
        );
        nbDocs += 1;
      } else if (typeDoc === "guide") {
        if (nbDocs > 0) doc.newPage();
        try {
          await genererBrochureGuideCompleteProf(p, `${location.origin}${location.pathname}`, doc);
        } catch (e) {
          // Pages illustrées de la brochure (guide_prof_p*.jpg) introuvables
          // à côté de l'application.
          toast(`⚠️ Brochure Guide Professeur indisponible : ${e?.message || e}`);
          return;
        }
        nbDocs += 1;
      }
    }
    if (nbDocs === 0) {
      toast(
        typeDoc === "planification"
          ? `⚠️ Aucune séance planifiée (${libelleSemestreIntervenant}, ${intAnnee}) pour ${seul ? nomIntervenant(liste[0]) : "ces intervenants"}`
          : `⚠️ Aucune date de contrôle continu ou d'examen saisie (${libelleSemestreIntervenant}, ${intAnnee}) pour ${seul ? nomIntervenant(liste[0]) : "ces intervenants"}`
      );
      return;
    }
    const noms = {
      planification: "Planification_cours",
      calendrier: "Calendrier_Examens",
      esrmi: "Calendrier_ESRMI",
      engagement: "Engagement_enseignant",
      guide: "Brochure_Guide_Utilisation",
    };
    const suffixe = seul ? `${liste[0].prenom || ""}_${liste[0].nom || ""}_${intAnnee}` : `${nbDocs}_intervenants_${today()}`;
    downloadPDF(doc.build(), `${noms[typeDoc]}_${suffixe}`.replace(/\s+/g, "_") + ".pdf");
    if (!seul) {
      toast(
        `✅ PDF généré — ${nbDocs} intervenant(s) dans un seul fichier` +
          (ignores.length ? ` (${ignores.length} sans donnée ignoré(s) : ${ignores.slice(0, 3).join(", ")}${ignores.length > 3 ? "…" : ""})` : "")
      );
    }
  };
  const CATEGORIES = [
    {
      id: "etudiant",
      label: "Scolarité",
      icon: "📄",
      iconeTrait: "ecole",
      sub: "Documents, relevés de notes, absences et paiements",
      gradient: "linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)",
      couleur: "#7c3aed",
    },
    {
      id: "intervenant",
      label: "Corps enseignant",
      icon: "🧑‍🏫",
      iconeTrait: "presentation",
      sub: "Documents des intervenants vacataires",
      gradient: "linear-gradient(135deg, #ea580c 0%, #f59e0b 100%)",
      couleur: "#ea580c",
    },
  ];
  const handleReleveAbsences = (etudiant) => {
    const presencesEtudiant = (data.presences || []).filter((p) => p.etudiantId === etudiant.id);
    genererReleveAbsences(etudiant, presencesEtudiant, data.cours);
  };
  // Génère, en un seul fichier PDF (une page — ou plusieurs pour un relevé
  // d'absences fourni — par étudiant), le même type de document pour les
  // étudiants cochés dans le tableau, ou à défaut pour TOUS les étudiants
  // correspondant aux filtres actuels de la page.
  const handleBatchDocumentEtudiant = (typeDoc) => {
    if (etudiantsCiblesDocs.length === 0) {
      toast("⚠️ Aucun étudiant ne correspond aux filtres actuels");
      return;
    }
    const W = 210 * MM,
      H = 297 * MM;
    const doc = new MiniPDF(W, H);
    etudiantsCiblesDocs.forEach((et, i) => {
      if (i > 0) doc.newPage();
      const filiereEt = filiereEtudiantPourAnnee(et, filterAnnee) || et.filiere;
      if (typeDoc === "absences") {
        const presencesEt = (data.presences || []).filter((p) => p.etudiantId === et.id);
        genererReleveAbsences(et, presencesEt, data.cours, doc);
      } else if (typeDoc === "stage") {
        genererConventionStage(et, filiereEt, filterAnnee, doc);
      } else if (typeDoc === "info") {
        const filiereObjEt = (data.filieres || []).find((f) => f.intitule === filiereEt);
        genererFicheInformations(et, filiereObjEt, filterAnnee, doc);
      } else if (typeDoc === "engagement") {
        genererEngagement(et, doc);
      } else {
        genererAttestation(et, filiereEt, typeDoc, filterAnnee, doc);
      }
    });
    const noms = {
      inscription: "Attestations_Inscription",
      scolarite: "Attestations_Scolarite",
      reussite: "Attestations_Reussite",
      stage: "Conventions_Stage",
      absences: "Releves_Absences",
      info: "Fiches_Informations",
      engagement: "Engagements",
    };
    downloadPDF(
      doc.build(),
      `${noms[typeDoc]}_${etudiantsCiblesDocs.length}_etudiants_${today()}`.replace(/\s+/g, "_") + ".pdf"
    );
    toast(`✅ PDF généré — ${etudiantsCiblesDocs.length} document(s) dans un seul fichier`);
  };
  const handleBatchBulletins = (type) => {
    if (etudiantsFiltres.length === 0) {
      toast("⚠️ Aucun étudiant ne correspond aux filtres actuels");
      return;
    }
    const W = 210 * MM,
      H = 297 * MM;
    const doc = new MiniPDF(W, H);
    etudiantsFiltres.forEach((et, i) => {
      if (i > 0) doc.newPage();
      const notesSem = (data.notes || []).filter(
        (n) => n.etudiantId === et.id && n.semestre === filterSemestre
      );
      if (type === "synthetique") {
        const presencesSem = (data.presences || []).filter((p) => p.etudiantId === et.id);
        genererBulletinNotes(
          et,
          notesSem,
          filterSemestre,
          filterAnnee,
          data.cours,
          presencesSem,
          data.configuration?.filieresAvecTauxAbsence,
          doc
        );
      } else {
        genererReleveDetaille(et, notesSem, filterSemestre, filterAnnee, doc);
      }
    });
    const suffixe = type === "synthetique" ? "Synthetiques" : "Detailles";
    downloadPDF(
      doc.build(),
      `Releves_${suffixe}_${etudiantsFiltres.length}_etudiants_${today()}`.replace(/\s+/g, "_") + ".pdf"
    );
    toast(`✅ PDF généré — ${etudiantsFiltres.length} relevé(s) dans un seul fichier`);
  };
  // Génère, en un seul fichier PDF, le relevé de notes (synthétique ou
  // détaillé) de chaque paire (étudiant, semestre) correspondant aux
  // filtres de la section "Relevés de notes" (année, groupe(s), semestre,
  // module, type d'évaluation, recherche).
  const handleRelevesNotesImpression = (type) => {
    if (pairesNotesImpression.length === 0) {
      toast("⚠️ Aucune note ne correspond aux filtres actuels");
      return;
    }
    const W = 210 * MM,
      H = 297 * MM;
    const doc = new MiniPDF(W, H);
    pairesNotesImpression.forEach((row, i) => {
      if (i > 0) doc.newPage();
      const etReel = (data.etudiants || []).find((e) => e.id === row.etudiantId);
      // La note garde elle-même la filière de l'étudiant au moment de
      // l'évaluation — c'est cette valeur historique qu'il faut imprimer,
      // pas la filière actuelle (qui peut avoir changé depuis).
      const et = {
        ...(etReel || { prenom: row.etudiant || "", nom: "" }),
        filiere: row._filiere || row.filiere || etReel?.filiere || "",
        numInscription: row.numInscription,
      };
      const semestre = row.semestre || "";
      const notesSem = (data.notes || []).filter(
        (n) => n.etudiantId === row.etudiantId && n.semestre === semestre && n.anneeUniversitaire === releveFilterAnnee
      );
      if (type === "synthetique") {
        const presencesSem = (data.presences || []).filter((p) => p.etudiantId === row.etudiantId);
        genererBulletinNotes(
          et,
          notesSem,
          semestre,
          releveFilterAnnee,
          data.cours,
          presencesSem,
          data.configuration?.filieresAvecTauxAbsence,
          doc
        );
      } else {
        genererReleveDetaille(et, notesSem, semestre, releveFilterAnnee, doc);
      }
    });
    const suffixe = type === "synthetique" ? "Synthetiques" : "Detailles";
    downloadPDF(
      doc.build(),
      `Releves_Notes_${suffixe}_${pairesNotesImpression.length}_${today()}`.replace(/\s+/g, "_") + ".pdf"
    );
    toast(`✅ PDF généré — ${pairesNotesImpression.length} relevé(s) dans un seul fichier`);
  };
  // Génère, en un seul fichier PDF, le relevé d'absences (synthétique par
  // module, ou détaillé séance par séance) de chaque étudiant correspondant
  // aux filtres de la section "Relevés des absences".
  const handleRelevesAbsencesImpression = (type) => {
    const liste = type === "synthetique" ? etudiantsBaseAbsences : etudiantsAvecAbsenceFiltree;
    if (liste.length === 0) {
      toast("⚠️ Aucun étudiant ne correspond aux filtres actuels");
      return;
    }
    const W = 210 * MM,
      H = 297 * MM;
    const doc = new MiniPDF(W, H);
    liste.forEach((et, i) => {
      if (i > 0) doc.newPage();
      if (type === "synthetique") {
        genererSyntheseAbsencesModule(
          et,
          data,
          {
            anneeUniversitaire: releveFilterAnnee,
            semestre: releveFilterSemestre,
            professeurCin: releveFilterProfesseur,
            moduleFiltre: releveFilterModule,
          },
          doc
        );
      } else {
        const presencesEt = presencesFiltreesImpression.filter((p) => p.etudiantId === et.id);
        genererReleveAbsences(et, presencesEt, data.cours, doc);
      }
    });
    const suffixe = type === "synthetique" ? "Synthetiques" : "Detailles";
    downloadPDF(doc.build(), `Releves_Absences_${suffixe}_${liste.length}_${today()}`.replace(/\s+/g, "_") + ".pdf");
    toast(`✅ PDF généré — ${liste.length} relevé(s) dans un seul fichier`);
  };
  // Génère, en un seul fichier PDF, le relevé de paiement (synthétique ou
  // détaillé) de chaque étudiant correspondant aux filtres de la section
  // "Relevés des paiements".
  const handleRelevesPaiementsImpression = (type) => {
    if (lignesPaiementsImpression.length === 0) {
      toast("⚠️ Aucun étudiant ne correspond aux filtres actuels");
      return;
    }
    const W = 210 * MM,
      H = 297 * MM;
    const doc = new MiniPDF(W, H);
    lignesPaiementsImpression.forEach((ligne, i) => {
      if (i > 0) doc.newPage();
      genererReleveEtatPaiement(ligne._etudiant, ligne._ep, type, releveFilterAnnee, doc);
    });
    const suffixe = type === "synthetique" ? "Synthetiques" : "Detailles";
    downloadPDF(
      doc.build(),
      `Releves_Paiements_${suffixe}_${lignesPaiementsImpression.length}_${today()}`.replace(/\s+/g, "_") + ".pdf"
    );
    toast(`✅ PDF généré — ${lignesPaiementsImpression.length} relevé(s) dans un seul fichier`);
  };
