      const heures = seancesDeFiche(f.id).reduce((s, x) => s + (x.nbHeures || 0), 0);
      const cle = f.professeurNom || "—";
      if (!lignesParProf[cle])
        lignesParProf[cle] = { professeur: cle, nbFiches: 0, nbSeances: 0, totalHeures: 0, montant: 0 };
      lignesParProf[cle].nbFiches += 1;
      lignesParProf[cle].nbSeances += seancesDeFiche(f.id).length;
