  ligneInfo("Année universitaire", champs.AnneeUniversitaire);
  ligneInfo("Motif", champs.Motif);
  ligneInfo("Mode de paiement", champs.Mode);
  if (champs.Banque) ligneInfo("Banque", champs.Banque);
