  const anneeUniv = anneeUnivParam || etudiant.promotion || ANNEES_UNIVERSITAIRES[0];
  const W = 210 * MM,
    H = 297 * MM;
  const titres = {
    inscription: "ATTESTATION D'INSCRIPTION",
    scolarite: "ATTESTATION DE SCOLARITÉ",
    reussite: "ATTESTATION DE RÉUSSITE",
  };
  // Civilité déduite du genre de l'étudiant (aucune information d'état
  // civil/matrimonial n'étant saisie dans l'application, "Mlle" est
  // utilisé par convention pour les étudiantes, comme c'est l'usage pour
  // ce niveau d'études).
  const estFeminin = etudiant.genre === "F";
  const civilite = estFeminin ? "Mlle" : "M.";
