  // Civilité selon le genre de l'étudiant : "M." ou "Mme", avec accord
  // des participes du texte (soussigné/soussignée, inscrit/inscrite).
  const estFeminin = etudiant.genre === "F";
  const civilite = estFeminin ? "Mme" : "M.";
  const accordE = (mot) => (estFeminin ? `${mot}e` : mot);
