  let y = H - 53 * MM;
  doc.textCentered(
    W / 2,
    y,
    `${(professeur?.prenom || fiche.professeurNom || "").toUpperCase()} ${(professeur?.nom || "").toUpperCase()}`.trim(),
    { size: 15, bold: true, color: NAVY_RGB }
  );
