// Impression : le PDF (mise en page papier, sans aucun élément d'interface)
// est chargé dans un cadre invisible puis envoyé à l'imprimante ; repli sur
// l'ouverture dans un nouvel onglet si le navigateur refuse.
function imprimerPDFRecettes(bytes) {
  const url = URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
  const cadre = document.createElement("iframe");
  cadre.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden";
  cadre.src = url;
  cadre.onload = () => {
    try {
      cadre.contentWindow.focus();
      cadre.contentWindow.print();
    } catch {
      window.open(url, "_blank");
    }
  };
  document.body.appendChild(cadre);
  setTimeout(() => {
    cadre.remove();
    URL.revokeObjectURL(url);
  }, 120000);
}
