function _buildSheetXmlXlsx(headers, rows) {
  let xml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>`;
  xml += `<row r="1">`;
  headers.forEach((h, ci) => {
    xml += `<c r="${_colLetterXlsx(ci)}1" t="inlineStr"><is><t xml:space="preserve">${_escXmlXlsx(h)}</t></is></c>`;
  });
  xml += `</row>`;
  rows.forEach((row, ri) => {
    const r = ri + 2;
    xml += `<row r="${r}">`;
    row.forEach((val, ci) => {
      const cellRef = `${_colLetterXlsx(ci)}${r}`;
      if (typeof val === "number" && isFinite(val)) {
        xml += `<c r="${cellRef}"><v>${val}</v></c>`;
      } else {
        xml += `<c r="${cellRef}" t="inlineStr"><is><t xml:space="preserve">${_escXmlXlsx(val)}</t></is></c>`;
      }
    });
    xml += `</row>`;
  });
  xml += `</sheetData></worksheet>`;
  return xml;
}
// Fonction principale : construit un classeur .xlsx authentique à partir
// de plusieurs feuilles : [{ name, headers, rows }].
function buildXlsxBytes(sheets) {
  const files = [];
  files.push({
    name: "[Content_Types].xml",
    data: _strToBytesXlsx(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
${sheets.map((s, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join("\n")}
</Types>`),
  });
  files.push({
    name: "_rels/.rels",
    data: _strToBytesXlsx(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`),
  });
  files.push({
    name: "xl/workbook.xml",
    data: _strToBytesXlsx(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheets>
${sheets.map((s, i) => `<sheet name="${_escXmlXlsx(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join("\n")}
</sheets>
</workbook>`),
  });
  files.push({
    name: "xl/_rels/workbook.xml.rels",
    data: _strToBytesXlsx(`<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
${sheets.map((s, i) => `<Relationship Id="rId${i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join("\n")}
</Relationships>`),
  });
  sheets.forEach((s, i) => {
    files.push({
      name: `xl/worksheets/sheet${i + 1}.xml`,
      data: _strToBytesXlsx(_buildSheetXmlXlsx(s.headers, s.rows)),
    });
  });
  return _buildZipXlsx(files);
}
function buildOperationsExcelXML(rows) {
  const esc = (s) =>
    String(s ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  const headerCells = [
    "Date",
    "Prénom",
    "Nom",
    "N° Inscription",
    "Année Universitaire",
    "Motif",
    "Montant (MAD)",
    "Mode",
    "Référence",
    "Reçu",
    "Agent",
  ]
    .map((h) => `<Cell><Data ss:Type="String">${esc(h)}</Data></Cell>`)
    .join("");
  const bodyRows = rows
    .map((v) => {
      const cells = [
        formatDateFR(v.date),
        v.etudiantPrenom,
        v.etudiantNom,
        v.numInscription,
        v.anneeUniversitaire || "",
        v.motif || "",
        v.montant,
        v.mode || "",
        v.reference || "",
        v.recu || "",
        v.agent || "",
      ]
        .map((val, i) =>
          i === 6
            ? `<Cell><Data ss:Type="Number">${Number(val) || 0}</Data></Cell>`
            : `<Cell><Data ss:Type="String">${esc(val)}</Data></Cell>`
        )
        .join("");
      return `<Row>${cells}</Row>`;
    })
    .join("");
  return `<?xml version="1.0"?>
<?mso-application progid="Excel.Sheet"?>
<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">
<Styles><Style ss:ID="hdr"><Font ss:Bold="1"/><Interior ss:Color="#1A2F5E" ss:Pattern="Solid"/><Font ss:Color="#FFFFFF" ss:Bold="1"/></Style></Styles>
<Worksheet ss:Name="Opérations"><Table>
<Row ss:StyleID="hdr">${headerCells}</Row>
${bodyRows}
</Table></Worksheet>
</Workbook>`;
}
async function exportOperationsToExcel(rows, token, toast) {
  const xml = buildOperationsExcelXML(rows);
  const filename = `Operations_Paiements_${today()}.xls`;
  const blob = new Blob([xml], { type: "application/vnd.ms-excel" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  if (!token) {
    toast?.("⚠️ Non connecté à SharePoint — fichier téléchargé localement uniquement");
    return;
  }
  try {
    const driveId = await getDriveIdCached(token);
    if (!driveId) {
      toast?.("⚠️ Impossible d'accéder au répertoire partagé — fichier téléchargé localement uniquement");
      return;
    }
    const res = await fetch(
      `https://graph.microsoft.com/v1.0/drives/${driveId}/root:/ECOGEST_Exports/${encodeURIComponent(filename)}:/content`,
      {
        method: "PUT",
        headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/vnd.ms-excel" },
        body: xml,
      }
    );
    if (!res.ok) {
      toast?.("⚠️ Échec de l'enregistrement dans le répertoire partagé");
      return;
    }
    toast?.(`Export enregistré dans SharePoint (Documents partagés/ECOGEST_Exports/${filename}) ✓`);
  } catch (e) {
    console.error("exportOperationsToExcel error:", e.message);
    toast?.("⚠️ Échec de l'enregistrement dans le répertoire partagé");
  }
}
const _colCache = {};
const _rawColsCache = {};
async function getRawCols(listName, token, siteId) {
  if (_rawColsCache[listName]) return _rawColsCache[listName];
  try {
    const res = await fetch(`https://graph.microsoft.com/v1.0/sites/${siteId}/lists/${listName}/columns`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    const data = await res.json();
    const cols = data.value || [];
    _rawColsCache[listName] = cols;
    return cols;
  } catch (e) {
    console.warn("getRawCols error:", e.message);
    return [];
  }
}
async function getColMap(listName, token, siteId) {
  if (_colCache[listName]) return _colCache[listName];
  const cols = await getRawCols(listName, token, siteId);
  const map = {};
  cols.forEach((c) => {
    map[c.displayName] = c.name;
    map[c.name] = c.name;
    map[c.displayName.toLowerCase()] = c.name;
    map[c.name.toLowerCase()] = c.name;
  });
  map["Title"] = "Title";
  _colCache[listName] = map;
  console.log(
    `📋 Colonnes ${listName}:`,
    Object.keys(map)
      .filter((k) => !k.includes("lower") && map[k].startsWith("field"))
      .map((k) => k + "->" + map[k])
  );
  return map;
}
async function getReverseColMap(listName, token, siteId) {
  const cols = await getRawCols(listName, token, siteId);
  const reverse = {};
  cols.forEach((c) => {
    reverse[c.name] = c.displayName;
  });
  reverse["Title"] = "Title";
  return reverse;
}
async function getColTypeMap(listName, token, siteId) {
  const cols = await getRawCols(listName, token, siteId);
  const types = {};
  cols.forEach((c) => {
    let type = "text";
    if (c.number || c.currency) type = "number";
    else if (c.boolean) type = "boolean";
    types[c.name] = type;
  });
  return types;
}
