function resolveSpId(spId, remap) {
  if (!spId) return null;
  return remap[spId] || spId;
}
async function flushOfflineQueue(token) {
  const queue = loadOfflineQueue();
  if (queue.length === 0) return { reussies: 0, echouees: 0, remap: {} };
  const remap = {};
  const restantes = [];
  let reussies = 0,
    echouees = 0;
  for (const item of queue) {
    try {
      if (item.type === "save") {
        const spIdReel = resolveSpId(item.spId, remap);
        const result = await saveToSPOnline(item.list, item.fields, token, spIdReel);
        if (result && result.id) {
          remap[item.tempId] = result.id;
          reussies++;
          if (item.notifier !== false) notifierOperation(item.list, "save", spIdReel, item.fields);
        } else {
          restantes.push(item);
          echouees++;
        }
      } else if (item.type === "delete") {
        const spIdReel = resolveSpId(item.spId, remap);
        const historiser = !LISTES_SANS_HISTORIQUE_SUPPRESSION.has(item.list) && !String(spIdReel).startsWith("offline-");
        const anciens = historiser ? await _lireElementCompletPourHistorique(item.list, spIdReel, token) : null;
        const ok = await deleteFromSPOnline(item.list, spIdReel, token);
        if (ok) {
          reussies++;
          if (item.notifier !== false) notifierOperation(item.list, "delete", spIdReel, null, anciens);
          if (anciens) _archiverSuppression(item.list, spIdReel, anciens, token);
        } else {
          restantes.push(item);
          echouees++;
        }
      }
    } catch (e) {
      restantes.push(item);
      echouees++;
    }
  }
  persistOfflineQueue(restantes);
  return { reussies, echouees, remap };
}
