// Photo de profil d'une personne, enregistrée dans la liste SharePoint
// ECOGEST_PhotosProfil (une fiche par email, image JPEG en base64).
async function chargerPhotoProfilSP(token, email) {
  const siteId = await getSiteIdCached(token);
  if (!siteId) return null;
  const res = await fetch(`https://graph.microsoft.com/v1.0/sites/${siteId}/lists/ECOGEST_PhotosProfil/items?expand=fields&$top=500`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return null;
  const json = await res.json();
  const item = (json.value || []).find((i) => String(i.fields?.UserEmail || "").toLowerCase() === email);
  return item ? { spId: item.id, photo: item.fields?.Photo || "" } : null;
}
// Recadre l'image au carré (centre) et la réduit à taille × taille en JPEG,
// pour une photo légère (quelques Ko) quelle que soit l'image choisie.
function redimensionnerPhotoProfil(fichier, taille = 160) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(fichier);
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = taille;
      const cote = Math.min(img.width, img.height);
      canvas.getContext("2d").drawImage(img, (img.width - cote) / 2, (img.height - cote) / 2, cote, cote, 0, 0, taille, taille);
      URL.revokeObjectURL(url);
      resolve(canvas.toDataURL("image/jpeg", 0.85));
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Image illisible — choisissez un fichier JPG ou PNG"));
    };
    img.src = url;
  });
}
